    local function fireFake(txt)
        txt = (txt or ""):gsub("^%s+", ""):gsub("%s+$", "")
        if txt == "" then return end

        -- Drive the bound handler directly rather than firesignal.
        --
        -- firesignal fires EVERY connection on the signal, and executors ignore
        -- Disable -- so it reaches the game's own notification handlers even though
        -- pole has disabled them. Pole then re-dispatches those same handlers itself,
        -- and one fake announcement came out as two popups. Reproduced in the fuzz rig
        -- as exactly that: one click, two game popups.
        --
        -- The bound handler is the path a real announcement takes anyway, it fires
        -- once, and it does not need firesignal to exist at all -- which several
        -- executors do not provide.
        -- With Auto Redeem on, the bound handler IS the real path -- threshold,
        -- buffer, guess mode and the send all already work through it.
        --
        -- With Auto Redeem off that handler is the idle one, so a fake went in and
        -- nothing came out: no send, and the parts did not even reach the buffer.
        -- Pressing Send is an explicit act, so it is forced through instead. Auto
        -- Redeem is about reacting to announcements on its own, not about a button
        -- you pressed. LUCK.SenderRedeems = false puts the old behaviour back for
        -- testing detection without spending an attempt.
        local fast = L.FastNotify
        if fast and L.AutoOn then
            pcall(fast, txt, 5.5, "Sounds.Sfx.Blop", "Top")
            L.Notify("sent fake: " .. txt, T.MUTED)
            return
        end
        if L.SenderRedeems ~= false and L.Dispatch then
            pcall(L.Dispatch, txt, true)
            L.Notify("sent fake: " .. txt .. "  (auto off, forced)", T.MUTED)
            return
        end
        if fast then
            pcall(fast, txt, 5.5, "Sounds.Sfx.Blop", "Top")
            L.Notify("sent fake: " .. txt, T.MUTED)
            return
        end

        local r = L.NotifyRemote
        if not (r and typeof(firesignal) == "function") then
            L.Notify("nothing bound to announce into", T.RED)
            return
        end
        pcall(firesignal, r.OnClientEvent, txt, 5.5,
            "Sounds.Sfx.Blop", "Top", 2678001507)
        L.Notify("sent fake: " .. txt, T.MUTED)
    end
    local SendBtn = New("TextButton", {Size = UDim2.new(1, -102, 0, 30),
        Position = UDim2.new(0, 10, 0, 42), BackgroundColor3 = T.ACCENT,
        BackgroundTransparency = 1, Text = "SEND", TextColor3 = T.VOID,
        Font = Enum.Font.GothamBold, TextSize = 12, TextTransparency = 1,
        AutoButtonColor = false, ClipsDescendants = true, Parent = C_Sender})
    Corner(SendBtn, 9)
    New("UIGradient", {Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0, T.DEEP),
        ColorSequenceKeypoint.new(0.5, T.ACCENT),
        ColorSequenceKeypoint.new(1, T.HIGH)}),
        Rotation = 90, Parent = SendBtn})
    rev(SendBtn, "BackgroundTransparency", 0)
    rev(SendBtn, "TextTransparency", 0)
    local TestBtn = New("TextButton", {Size = UDim2.new(0, 82, 0, 30),
        Position = UDim2.new(1, -92, 0, 42), BackgroundColor3 = T.RAISED,
        BackgroundTransparency = 1, Text = "TEST CODE", TextColor3 = T.ACCENT,
        Font = Enum.Font.GothamBold, TextSize = 10, TextTransparency = 1,
        AutoButtonColor = false, Parent = C_Sender})
    Corner(TestBtn, 9)
    local TestStroke = Stroke(TestBtn, T.ACCENT, 1)
    rev(TestBtn, "BackgroundTransparency", 0)
    rev(TestBtn, "TextTransparency", 0)
    rev(TestStroke, "Transparency", 0.45)
    -- One submit path for both the button and the Enter key.
    --
    -- These were two independent handlers, each of which read SendBox.Text, fired, and
    -- only then cleared it. Clicking SEND while the box has focus makes the box lose
    -- focus, so both handlers ran for one action and the announcement went out twice --
    -- and because each read the text before either cleared it, both read the same code.
    -- CaptureFocus() called from inside FocusLost compounded it: it re-focuses the box
    -- while that event is still being handled, which can hand back a second FocusLost.
    --
    -- The text is taken and cleared BEFORE anything is sent now, so whichever handler
    -- arrives second reads an empty box and stops. A short repeat guard covers any
    -- platform that manages to deliver both before the clear lands, and the refocus is
    -- deferred so it cannot re-enter the handler that scheduled it.
    local lastFake, lastFakeAt = nil, 0
    local function submitFake(text)
        local txt = (text or ""):gsub("^%s+", ""):gsub("%s+$", "")
        if txt == "" then return end
        local now = os.clock()
        if txt == lastFake and (now - lastFakeAt) < 0.35 then return end
        lastFake, lastFakeAt = txt, now
        fireFake(txt)
    end
    local function submitFromBox()
        local txt = SendBox.Text
        SendBox.Text = ""
        submitFake(txt)
        task.defer(function()
            if SendBox.Parent then pcall(function() SendBox:CaptureFocus() end) end
        end)
    end
    -- Exposed so the fuzz suite can drive the real submit path with real text.
    L.SenderSubmit, L.SenderBox = submitFromBox, SendBox
    SendBtn.MouseButton1Click:Connect(submitFromBox)
    SendBox.FocusLost:Connect(function(enter)
        if enter then submitFromBox() end
    end)
    TestBtn.MouseButton1Click:Connect(function()
        submitFake("TESTCODE" .. tostring(math.random(1000, 9999)))
    end)
    hover(TestBtn, T.RAISED, TestStroke)

    local ToastHolder = New("Frame", {Size = UDim2.new(0, 340, 1, -60),
        Position = UDim2.new(0.5, -170, 0, 14), BackgroundTransparency = 1,
        Parent = Gui})
    New("UIListLayout", {SortOrder = Enum.SortOrder.LayoutOrder,
        HorizontalAlignment = Enum.HorizontalAlignment.Center,
        Padding = UDim.new(0, 6), Parent = ToastHolder})
    local toastOrder = 0
    local toastRows = {}
    local function toast(text, color)
        toastOrder += 1
        local t = New("TextLabel", {Size = UDim2.new(1, 0, 0, 30),
            BackgroundColor3 = T.BG, BackgroundTransparency = 0.15,
            Text = tostring(text), TextColor3 = color or T.TEXT,
            Font = Enum.Font.GothamSemibold, TextSize = 12,
            TextTransparency = 1, BorderSizePixel = 0,
            LayoutOrder = toastOrder, Parent = ToastHolder})
        Corner(t, 9)
        local ts = Stroke(t, T.ACCENT, 1)
        ts.Transparency = 0.6
        -- Full opacity on creation. It used to be born invisible and tweened in over
        -- 250ms, so the result was legible a quarter of a second after it existed.
        t.TextTransparency = 0
        -- The dismissal stays on a timer -- a toast that never leaves is worse than a
        -- late one -- but it is a plain destroy, not a fade and a wait.
        task.delay(3.5, function()
            if t and t.Parent then t:Destroy() end
        end)
        -- Same FIFO treatment as the feed: no GetChildren() walk per toast. Note the
        -- old walk trimmed by child order, which is creation order, so it destroyed the
        -- newest ones past four rather than the oldest. This drops the oldest.
        toastRows[#toastRows + 1] = t
        while #toastRows > 4 do
            local old = table.remove(toastRows, 1)
            if old then pcall(function() old:Destroy() end) end
        end
    end

    -- No IntroDone gate on either of these any more. The panels exist by the time
    -- these are bound, and a redeem that lands during the intro is exactly the one you
    -- want to see -- it used to be dropped on the floor.
    L.Notify = function(text, color)
        feedLine("» " .. tostring(text), color or T.TEXT)
        toast("» " .. tostring(text), color or T.TEXT)
    end
    L.NotifyRedeem = function(code, prize, who)
        local nm = (who and who.Name) or "?"
        local msg = ("⚔ %s sniped %s%s"):format(nm, tostring(code or "?"),
            prize and ("  (" .. tostring(prize) .. ")") or "")
        feedLine(msg, T.ORANGE)
        toast(msg, T.ORANGE)
    end

    local function runManual()
        local code = CodeBox.Text:gsub("[^%w]", ""):upper():sub(1, 50)
        if code == "" then return end
        CodeBox.Text = ""
        task.spawn(function()
            local ok, reply, timing = L.RedeemViaRemote(code)
            L.PostRedeem(os.clock(), "manual", code, ok, reply, timing)
        end)
    end
    RedeemBtn.MouseButton1Click:Connect(runManual)
    CodeBox.FocusLost:Connect(function(enter)
        if enter then runManual() end
    end)

    L.RefreshAuto = function()
        L.RefreshPreview()
    end

    local function paintViewSwitch()
        local adv = L.ViewMode == "advanced"
        tw(stdBtn, 0.15, {BackgroundColor3 = (not adv) and T.ACCENT or T.RAISED,
                          TextColor3 = (not adv) and T.VOID or T.MUTED})
        tw(advBtn, 0.15, {BackgroundColor3 = adv and T.ACCENT or T.RAISED,
                          TextColor3 = adv and T.VOID or T.MUTED})
    end
    local function applyViewMode()
        local adv = L.ViewMode == "advanced"
        for name, p in pairs(panels) do
            if name ~= "Main" then
                p.frame.Visible = adv and L.IntroDone == true
            end
        end
        paintViewSwitch()
    end
    L.SetViewMode = function(m)
        L.ViewMode = (m == "advanced") and "advanced" or "standard"
        L.Settings.ViewMode = L.ViewMode
        L.SaveSettings()
        applyViewMode()
    end
    stdBtn.MouseButton1Click:Connect(function() L.SetViewMode("standard") end)
    advBtn.MouseButton1Click:Connect(function() L.SetViewMode("advanced") end)

    local Fab = New("TextButton", {Size = UDim2.new(0, 46, 0, 46),
        Position = UDim2.new(0, 18, 1, -64), BackgroundColor3 = T.BG,
        BackgroundTransparency = 1, Text = "🍀", TextSize = 24,
        Font = Enum.Font.GothamBold, TextTransparency = 1,
        AutoButtonColor = false, Visible = false, Parent = Gui})
    Corner(Fab, 14)
    local FabStroke = Stroke(Fab, T.ACCENT)
    rev(Fab, "BackgroundTransparency", 0.06)
    rev(Fab, "TextTransparency", 0)
    rev(FabStroke, "Transparency", 0.45)

    local mainShown = true
    local function toggleAll()
        mainShown = not mainShown
        panels["Main"].frame.Visible = mainShown and L.IntroDone == true
        if mainShown then applyViewMode() else
            for name, p in pairs(panels) do
                if name ~= "Main" then p.frame.Visible = false end
            end
        end
    end
    Fab.MouseButton1Click:Connect(toggleAll)

    local function keycode(name)
        local ok, kc = pcall(function() return Enum.KeyCode[name] end)
        return ok and kc or nil
    end
    local kbAuto = keycode(L.Settings.Keybinds.Auto) or Enum.KeyCode.F
    local kbUI = keycode(L.Settings.Keybinds.ToggleUI) or Enum.KeyCode.G
    UIS.InputBegan:Connect(function(input, gpe)
        if gpe then return end
        if input.KeyCode == kbAuto then
            setAuto(not L.AutoOn)
        elseif input.KeyCode == kbUI then
            toggleAll()
        end
    end)

    paintModes()
    paintSwitches()
    paintParts()
    paintSpeed()
    paintViewSwitch()
    L.RefreshHistory()

    task.spawn(function()
        L.IntroDone = true
        Fab.Visible = true
        panels["Main"].frame.Visible = true
        applyViewMode()
        for _, p in pairs(panels) do
            if p.frame.Visible then
                local sc = New("UIScale", {Scale = 0.92, Parent = p.frame})
                tw(sc, 0.25, {Scale = 1})
                task.delay(0.3, function() sc:Destroy() end)
            end
        end
        for _, e in ipairs(reveal) do
            tw(e[1], 0.35, {[e[2]] = e[3]})
        end
        task.delay(0.4, function()
            L.Notify("🍀 LUCK online", T.HIGH)
            -- Anything caught before the panels existed, replayed in order now that
            -- there is somewhere to put it.
            local backlog = L.NotifyBacklog
            if backlog then
                L.NotifyBacklog = nil
                for i = 1, #backlog do
                    L.Notify(backlog[i][1], backlog[i][2])
                end
            end
            if status then
                local waited = L.ReadyAt and (" · up in %.2fs"):format(L.UpIn or 0) or ""
                status.set("ready  ·  detect " .. L.DetectMode
                    .. "  ·  redeem " .. L.RedeemPath .. waited, T.MUTED)
            end
        end)
    end)
end

-- The UI is the last thing to happen, not the first. Everything above resolved the
-- remotes, connected detection, tested the redeem and took pole; only then does a
-- single Instance.new run. On a place where some of that never resolved the gate opens
-- on its own deadline, so the panel always comes up -- LUCK.Diag() says which it was.
L.BuildUI = function()
    if L.UIBuilt then return true end
    L.UIBuilt = true
    L.UpIn = os.clock() - (L.LoadedAt or os.clock())
    local ok, err = pcall(buildUI)
    if not ok then
        L.UIError = tostring(err)
        warn("[LUCK] UI failed to build: " .. tostring(err))
    end
    return ok
end
L.WhenReady(L.BuildUI)

--[[ ====================================================================
     LUCK PRIVATE  ·  living gradient theme engine

     Appended to the base script rather than forked into it, so the private
     build is always the public one plus this file and the two cannot drift.
     It touches nothing on the detection or send path -- it finds the panels
     after they exist, puts a UIGradient on each, and drives them.

     Ten palettes. Rainbow is a real hue sweep; the rest are hand-picked
     ramps. Pick with the THEME panel, LUCK.SetTheme("Ruby"), or the cycle
     key. The choice is saved.
     ==================================================================== ]]

do

local L = (getgenv and getgenv().LUCK) or LUCK
if not L then return end

local RS   = game:GetService("RunService")
local UIS  = game:GetService("UserInputService")
local HTTP = game:GetService("HttpService")

local rgb   = Color3.fromRGB
local hsv   = Color3.fromHSV
local floor = math.floor

L.Private = true
L.PrivateBuild = "1.0"

-- --------------------------------------------------------------------
-- Palettes
--
-- Colors is the ramp the gradient flows through, and it wraps: the engine
-- appends the first colour to the end so the loop has no seam. Accent is
-- what the swatch and the picker highlight use.
-- --------------------------------------------------------------------
local THEMES = {
    {name = "Rainbow", hue = true, accent = rgb(255, 120, 200)},

    {name = "Clover",  accent = rgb(95, 235, 145), colors = {
        rgb(24, 92, 54), rgb(45, 165, 95), rgb(95, 235, 145), rgb(170, 255, 205)}},

    {name = "Toxic",   accent = rgb(130, 255, 55), colors = {
        rgb(48, 110, 16), rgb(98, 210, 38), rgb(130, 255, 55), rgb(210, 255, 120)}},

    {name = "Mint",    accent = rgb(90, 230, 190), colors = {
        rgb(20, 105, 82), rgb(50, 180, 140), rgb(90, 230, 190), rgb(180, 255, 230)}},

    {name = "Aqua",    accent = rgb(80, 205, 230), colors = {
        rgb(20, 82, 115), rgb(45, 150, 195), rgb(80, 205, 230), rgb(160, 245, 255)}},

    {name = "Ice",     accent = rgb(112, 190, 255), colors = {
        rgb(34, 92, 165), rgb(70, 155, 235), rgb(112, 190, 255), rgb(205, 238, 255)}},

    {name = "Grape",   accent = rgb(150, 112, 255), colors = {
        rgb(62, 34, 130), rgb(112, 68, 205), rgb(150, 112, 255), rgb(210, 186, 255)}},

    {name = "Sakura",  accent = rgb(236, 105, 168), colors = {
        rgb(112, 30, 82), rgb(190, 72, 140), rgb(236, 105, 168), rgb(255, 186, 222)}},

    {name = "Gold",    accent = rgb(220, 172, 64), colors = {
        rgb(102, 68, 16), rgb(180, 126, 38), rgb(220, 172, 64), rgb(255, 230, 145)}},

    {name = "Lava",    accent = rgb(255, 90, 40), colors = {
        rgb(112, 26, 6), rgb(190, 52, 16), rgb(255, 90, 40), rgb(255, 178, 100)}},

    -- Yours. Four slots, driven by the sliders, saved between sessions. Starts as
    -- a copy of Clover so it is something rather than four blacks.
    {name = "Custom",  custom = true, accent = rgb(95, 235, 145), colors = {
        rgb(24, 92, 54), rgb(45, 165, 95), rgb(95, 235, 145), rgb(170, 255, 205)}},
}

local byName = {}
for i, t in ipairs(THEMES) do
    t.index = i
    byName[t.name] = t
end
L.Themes = THEMES
local CUSTOM = byName.Custom

-- rampFor and uiFor both cache what they derive, which is right for the fixed
-- palettes and wrong for this one -- a slider that moves has to drop both or the
-- panel keeps painting the colour you just changed away from.
local function invalidate(theme)
    theme.ramp, theme.ui = nil, nil
end
L.ThemeNames = (function()
    local out = table.create(#THEMES)
    for i, t in ipairs(THEMES) do out[i] = t.name end
    return out
end)()

-- --------------------------------------------------------------------
-- Knobs
-- --------------------------------------------------------------------
L.ThemeOn    = true      -- false freezes every gradient where it stands
L.ThemeFps   = 30        -- gradient updates per second, NOT per frame
L.ThemeSpeed = 0.14      -- laps per second through the ramp
L.ThemeSpan  = 0.85      -- how much of the ramp is visible at once
L.ThemeKeys  = 20        -- keypoints per gradient
L.ThemeTilt  = 35        -- gradient rotation, degrees

local IS_MOBILE = L.IsMobile == true
if IS_MOBILE then
    -- A phone does not need 30 rebuilds a second of a cosmetic sweep.
    L.ThemeFps, L.ThemeKeys = 15, 10
end

-- --------------------------------------------------------------------
-- Sampling
-- --------------------------------------------------------------------
local function fract(x) return x - floor(x) end

local function scale(c, k)
    return Color3.new(math.clamp(c.R * k, 0, 1),
                      math.clamp(c.G * k, 0, 1),
                      math.clamp(c.B * k, 0, 1))
end
local function toward(c, target, a) return c:Lerp(target, a) end
local WHITE = Color3.new(1, 1, 1)

-- The flat palette the widgets read, derived from the ramp rather than written
-- out ten times by hand -- ten hand-tuned tables is ten chances for one of them
-- to be subtly wrong, and derived ones stay consistent when a ramp is edited.
local function uiFor(theme)
    if theme.ui then return theme.ui end
    if theme.hue then
        -- A hue sweep has no single colour to build a palette from, so Rainbow
        -- gets a neutral one: near-black chrome and near-white text, which is
        -- what lets the sweep itself be the colour.
        theme.ui = {
            VOID    = Color3.fromRGB(6, 6, 9),
            BG      = Color3.fromRGB(11, 11, 16),
            SURFACE = Color3.fromRGB(17, 17, 24),
            RAISED  = Color3.fromRGB(26, 26, 36),
            LINE    = Color3.fromRGB(48, 48, 64),
            ACCENT  = Color3.fromRGB(255, 120, 200),
            HIGH    = Color3.fromRGB(255, 205, 235),
            DEEP    = Color3.fromRGB(150, 60, 190),
            TEXT    = Color3.fromRGB(238, 238, 246),
            MUTED   = Color3.fromRGB(140, 138, 156),
        }
        return theme.ui
    end
    local c = theme.colors
    local dark, mid, bright, light = c[1], c[2], c[3], c[4]
    theme.ui = {
        VOID    = scale(dark, 0.16),
        BG      = scale(dark, 0.28),
        SURFACE = scale(dark, 0.42),
        RAISED  = scale(dark, 0.62),
        LINE    = scale(mid,  0.52),
        ACCENT  = bright,
        HIGH    = light,
        DEEP    = dark,
        TEXT    = toward(light, WHITE, 0.55),
        MUTED   = scale(toward(mid, WHITE, 0.2), 0.62),
    }
    return theme.ui
end

-- Ramps are built once per theme and cached. Rebuilding the keypoint table
-- every tick is unavoidable -- ColorSequence is immutable -- but rebuilding
-- the *ramp* it samples from is not.
local function rampFor(theme)
    if theme.ramp then return theme.ramp end
    local c = theme.colors
    local n = #c
    local ramp = table.create(n + 1)
    for i = 1, n do ramp[i] = {t = (i - 1) / n, v = c[i]} end
    ramp[n + 1] = {t = 1, v = c[1]}   -- wrap, so the loop has no seam
    theme.ramp = ramp
    return ramp
end

local function sampleOf(theme)
    if theme.hue then
        return function(u) return hsv(fract(u), 0.82, 1) end
    end
    local ramp = rampFor(theme)
    local n = #ramp
    return function(u)
        u = fract(u)
        for i = 1, n - 1 do
            local a, b = ramp[i], ramp[i + 1]
            if u >= a.t and u <= b.t then
                local span = b.t - a.t
                return a.v:Lerp(b.v, span > 0 and (u - a.t) / span or 0)
            end
        end
        return ramp[n].v
    end
end

-- --------------------------------------------------------------------
-- Registry
--
-- Flat arrays, walked once. The original this grew out of ran one
-- RenderStepped per gradient and re-walked the whole GUI tree ~28 times a
-- second to find strokes; at 999 fps that is a real main-thread bill for a
-- cosmetic effect. One connection, one throttle, no tree walks at runtime.
-- --------------------------------------------------------------------
local gradients, strokes, swatches, flowText = {}, {}, {}, {}
local tinted = {}          -- every widget captured at boot, with its boot colours
local conn, tAccum, frameAccum = nil, 0, 0
local themedGui

local function currentTheme()
    return byName[L.Theme] or THEMES[1]
end

local function anyVisible()
    for i = 1, #gradients do
        local g = gradients[i]
        local p = g.Parent
        if p and p.Visible then return true end
    end
    return false
end

local function paintStatic()
    local sample = sampleOf(currentTheme())
    local n = L.ThemeKeys
    local kps = table.create(n)
    for i = 1, n do
        local t = (i - 1) / (n - 1)
        kps[i] = ColorSequenceKeypoint.new(t, sample(t * L.ThemeSpan))
    end
    local seq = ColorSequence.new(kps)
    for i = #gradients, 1, -1 do
        local g = gradients[i]
        if g.Parent then g.Color, g.Rotation = seq, L.ThemeTilt
        else table.remove(gradients, i) end
    end
    local a, b = sample(0), sample(0.35)
    for i = #strokes, 1, -1 do
        local s = strokes[i]
        if s.Parent then s.Color = s.Thickness > 1 and a or b
        else table.remove(strokes, i) end
    end
    for i = #flowText, 1, -1 do
        local e = flowText[i]
        if e.Parent then e.TextColor3 = b else table.remove(flowText, i) end
    end
end

local function tick(dt)
    if not L.ThemeOn then return end
    frameAccum += dt
    local rate = 1 / math.max(1, L.ThemeFps)
    if frameAccum < rate then return end
    tAccum += frameAccum
    frameAccum = 0
    if not anyVisible() then return end

    local sample = sampleOf(currentTheme())
    local n = L.ThemeKeys
    local head = fract(tAccum * L.ThemeSpeed)
    local kps = table.create(n)
    for i = 1, n do
        local t = (i - 1) / (n - 1)
        kps[i] = ColorSequenceKeypoint.new(t, sample(head + t * L.ThemeSpan))
    end
    local seq = ColorSequence.new(kps)

    -- Backwards, so dropping a destroyed entry does not shift the ones
    -- still to come.
    for i = #gradients, 1, -1 do
        local g = gradients[i]
        if g.Parent then g.Color = seq else table.remove(gradients, i) end
    end
    local a, b = sample(head), sample(head + 0.35)
    for i = #strokes, 1, -1 do
        local s = strokes[i]
        if s.Parent then s.Color = s.Thickness > 1 and a or b
        else table.remove(strokes, i) end
    end
    -- The headline text -- panel titles, section tags, the FAB -- rides the
    -- sweep too. A fixed set collected once at boot, so this cannot grow.
    for i = #flowText, 1, -1 do
        local e = flowText[i]
        if e.Parent then e.TextColor3 = b else table.remove(flowText, i) end
    end
    for i = #swatches, 1, -1 do
        local sw = swatches[i]
        if sw.frame.Parent then
            sw.grad.Color = sw.theme.hue and seq or sw.grad.Color
        else table.remove(swatches, i) end
    end
end

local function start()
    if conn then return end
    conn = RS.RenderStepped:Connect(tick)
end
local function stop()
    if not conn then return end
    conn:Disconnect()
    conn = nil
end
L.ThemeStop = stop
L.ThemeStart = start

-- --------------------------------------------------------------------
-- Attaching to the panels
-- --------------------------------------------------------------------
local function findGui()
    local parent = L.GuiParent
    if not parent then return nil end
    for _, d in ipairs(parent:GetChildren()) do
        if d:IsA("ScreenGui") and tostring(d.Name):match("^LUCK_%d+$") then
            return d
        end
    end
    return nil
end

-- Top-level chrome only: the panel bodies, the FAB, their outlines. Everything
-- else is a label, a pill or a row -- mostly transparent, so a gradient on it
-- shows nothing, and each one would still cost a write every tick.
--
-- Deliberately NOT filtered on BackgroundTransparency: when this runs every
-- panel is still fully transparent and only tweens up during the intro, so that
-- test would reject all of them.
local function attach(inst)
    local parent = inst.Parent
    if parent ~= themedGui and (parent == nil or parent.Parent ~= themedGui) then
        return
    end
    if inst:IsA("UIStroke") then
        strokes[#strokes + 1] = inst
        return
    end
    if not inst:IsA("Frame") and not inst:IsA("TextButton") then return end
    if parent ~= themedGui then return end
    if inst:FindFirstChild("LuckThemeGradient") then return end
    local g = Instance.new("UIGradient")
    g.Name = "LuckThemeGradient"
    g.Rotation = L.ThemeTilt
    g.Transparency = NumberSequence.new(0.45)
    g.Parent = inst
    gradients[#gradients + 1] = g
end

-- --------------------------------------------------------------------
-- Retinting the whole UI
--
-- The gradient only ever covered the panel bodies, so with a theme picked the
-- rest of the UI stayed the colour it was built in. Fixing that has two halves.
--
-- Half one: rewrite the palette the base script reads its colours from. Widgets
-- read it at creation time, so every toast, feed line and history row built
-- after a theme change comes out in the new colours with nothing to walk.
--
-- Half two: the widgets that already exist were built from the old palette, so
-- they need one pass. Their boot colours are captured once, and every theme
-- change maps boot colour -> new colour from that snapshot. Mapping from the
-- CURRENT colour would work exactly once: after the first change nothing
-- matches the palette it was compared against any more.
--
-- One walk per theme change, which is a click. Nothing per frame, nothing on
-- the path of a redeem.
-- --------------------------------------------------------------------
local PAL_KEYS = {"VOID", "BG", "SURFACE", "RAISED", "LINE",
                  "ACCENT", "HIGH", "DEEP", "TEXT", "MUTED"}
local bootPalette

local function keyOf(c)
    if not c then return nil end
    return floor(c.R * 255 + 0.5) * 65536
         + floor(c.G * 255 + 0.5) * 256
         + floor(c.B * 255 + 0.5)
end

local function capture()
    table.clear(tinted)
    if not themedGui then return end
    for _, d in ipairs(themedGui:GetDescendants()) do
        local rec
        local okBg = pcall(function()
            if d:IsA("GuiObject") then rec = {bg = d.BackgroundColor3} end
        end)
        if not okBg or not rec then rec = {} end
        pcall(function()
            if d:IsA("TextLabel") or d:IsA("TextButton") or d:IsA("TextBox") then
                rec.text = d.TextColor3
            end
        end)
        pcall(function()
            if d:IsA("UIStroke") then rec.stroke = d.Color end
        end)
        if rec.bg or rec.text or rec.stroke then
            rec.inst = d
            tinted[#tinted + 1] = rec
        end
    end
end

local function applyPalette(theme)
    local P = L.Palette
    if not P then return end
    if not bootPalette then
        bootPalette = {}
        for _, k in ipairs(PAL_KEYS) do bootPalette[k] = P[k] end
    end

    local ui = uiFor(theme)
    local remap = {}
    for _, k in ipairs(PAL_KEYS) do
        local from, to = bootPalette[k], ui[k]
        if from and to then remap[keyOf(from)] = to end
        if to then P[k] = to end          -- half one: everything built from here on
    end

    -- half two: the widgets that already exist
    for i = #tinted, 1, -1 do
        local rec = tinted[i]
        local d = rec.inst
        if not d.Parent then
            table.remove(tinted, i)
        else
            if rec.bg then
                local to = remap[keyOf(rec.bg)]
                if to then pcall(function() d.BackgroundColor3 = to end) end
            end
            if rec.text then
                local to = remap[keyOf(rec.text)]
                if to then pcall(function() d.TextColor3 = to end) end
            end
            if rec.stroke then
                local to = remap[keyOf(rec.stroke)]
                if to then pcall(function() d.Color = to end) end
            end
        end
    end

    -- the base repaints these from the palette, so let it
    for _, fn in ipairs({L.PaintModes, L.RefreshHistory, L.RefreshPreview,
                         L.PaintCooldown, L.PaintSwitches, L.PaintSpeed}) do
        if type(fn) == "function" then pcall(fn) end
    end
end

local function attachAll()
    themedGui = findGui()
    if not themedGui then return false end
    table.clear(gradients)
    table.clear(strokes)
    table.clear(flowText)
    for _, d in ipairs(themedGui:GetDescendants()) do attach(d) end
    capture()

    -- The headline text rides the sweep: anything built in the accent or the
    -- highlight colour. Collected once from the boot snapshot, so it is a fixed
    -- set and cannot grow with traffic.
    do
        local P = L.Palette
        local hot = P and {[keyOf(P.ACCENT)] = true, [keyOf(P.HIGH)] = true} or {}
        for _, rec in ipairs(tinted) do
            if rec.text and hot[keyOf(rec.text)] then
                flowText[#flowText + 1] = rec.inst
            end
        end
    end
    -- No DescendantAdded hook, on purpose. The top-level chrome is built once
    -- and never added to again; the things that DO keep arriving are toasts,
    -- feed lines and history rows, and those are not themed. A hook would put a
    -- Lua callback on the creation of every one of them -- and the first version
    -- did exactly that, took every UIStroke it was handed, and grew a list that
    -- held destroyed instances alive between ticks. Measured cost of that on the
    -- SEND path, from GC pressure alone: 171ns -> 315ns. One walk here, nothing
    -- on the hot path, and the picker registers its own pieces as it builds them.
    applyPalette(currentTheme())
    paintStatic()
    start()
    return true
end

-- --------------------------------------------------------------------
-- Choosing
-- --------------------------------------------------------------------
local THEME_FILE  = "LUCK/private_theme.txt"
local MIN_FILE    = "LUCK/private_theme_min.txt"
local CUSTOM_FILE = "LUCK/private_theme_custom.txt"
local function saveTheme()
    pcall(function()
        if type(makefolder) == "function"
            and (type(isfolder) ~= "function" or not isfolder("LUCK")) then
            makefolder("LUCK")
        end
        writefile(THEME_FILE, tostring(L.Theme))
    end)
end
local function loadTheme()
    local ok, v = pcall(function()
        if type(isfile) == "function" and not isfile(THEME_FILE) then return nil end
        return readfile(THEME_FILE)
    end)
    if ok and type(v) == "string" and byName[v] then return v end
    return nil
end

L.Theme = loadTheme() or "Rainbow"

-- --------------------------------------------------------------------
-- The custom palette
--
-- Four slots, dark to light, which is the order the ramp flows through.
-- Stored as plain "r,g,b" lines so it stays readable and a bad file loses the
-- colours rather than the script.
-- --------------------------------------------------------------------
local CUSTOM_SLOTS = 4

local function saveCustom()
    local out = table.create(CUSTOM_SLOTS)
    for i = 1, CUSTOM_SLOTS do
        local c = CUSTOM.colors[i]
        out[i] = ("%d,%d,%d"):format(floor(c.R * 255 + 0.5),
            floor(c.G * 255 + 0.5), floor(c.B * 255 + 0.5))
    end
    pcall(function()
        if type(makefolder) == "function"
            and (type(isfolder) ~= "function" or not isfolder("LUCK")) then
            makefolder("LUCK")
        end
        writefile(CUSTOM_FILE, table.concat(out, "\n"))
    end)
end

local function loadCustom()
    local ok, raw = pcall(function()
        if type(isfile) == "function" and not isfile(CUSTOM_FILE) then return nil end
        return readfile(CUSTOM_FILE)
    end)
    if not ok or type(raw) ~= "string" then return end
    local i = 0
    for line in raw:gmatch("[^\n]+") do
        local r, g, b = line:match("^(%d+),(%d+),(%d+)$")
        if r then
            i += 1
            if i <= CUSTOM_SLOTS then
                CUSTOM.colors[i] = rgb(tonumber(r), tonumber(g), tonumber(b))
            end
        end
    end
    invalidate(CUSTOM)
end
loadCustom()

L.CustomSlots = CUSTOM_SLOTS
L.GetCustomColor = function(slot)
    local c = CUSTOM.colors[slot]
    if not c then return nil end
    return floor(c.R * 255 + 0.5), floor(c.G * 255 + 0.5), floor(c.B * 255 + 0.5)
end

local refreshCustomUI
L.SetCustomColor = function(slot, r, g, b)
    slot = tonumber(slot)
    if not slot or slot < 1 or slot > CUSTOM_SLOTS then return false end
    r = math.clamp(tonumber(r) or 0, 0, 255)
    g = math.clamp(tonumber(g) or 0, 0, 255)
    b = math.clamp(tonumber(b) or 0, 0, 255)
    CUSTOM.colors[slot] = rgb(r, g, b)
    -- Slot 3 is the bright one the derived palette uses for its accent, so it is
    -- what the swatch and the picker highlight follow.
    if slot == 3 then CUSTOM.accent = CUSTOM.colors[3] end
    invalidate(CUSTOM)
    saveCustom()
    if refreshCustomUI then refreshCustomUI() end
    if L.Theme == "Custom" and L.ApplyTheme then L.ApplyTheme() end
    return true
end

L.RandomCustom = function()
    -- One hue, four steps along it. Random per channel gives mud; a single hue
    -- ramped dark to light gives something that actually reads as a theme.
    local h = math.random()
    for i = 1, CUSTOM_SLOTS do
        local t = (i - 1) / (CUSTOM_SLOTS - 1)
        local c = hsv(h, 0.85 - t * 0.45, 0.35 + t * 0.65)
        CUSTOM.colors[i] = c
    end
    CUSTOM.accent = CUSTOM.colors[3]
    invalidate(CUSTOM)
    saveCustom()
    if refreshCustomUI then refreshCustomUI() end
    if L.Theme == "Custom" and L.ApplyTheme then L.ApplyTheme() end
    return true
end

local repaintPicker
L.ApplyTheme = function()
    local t = currentTheme()
    applyPalette(t)
    paintStatic()
    if repaintPicker then repaintPicker() end
end

L.SetTheme = function(name)
    local t = byName[tostring(name)]
    if not t then
        print("[LUCK] themes: " .. table.concat(L.ThemeNames, ", "))
        return false, "unknown theme"
    end
    L.Theme = t.name
    saveTheme()
    applyPalette(t)
    paintStatic()
    if repaintPicker then repaintPicker() end
    if L.Notify then L.Notify("theme · " .. t.name, t.accent) end
    return true
end

L.NextTheme = function()
    local cur = currentTheme().index
    return L.SetTheme(THEMES[(cur % #THEMES) + 1].name)
end

L.ThemePrint = function()
    print("[LUCK] theme " .. tostring(L.Theme)
        .. "   (" .. #THEMES .. " available)")
    print("[LUCK] " .. table.concat(L.ThemeNames, ", "))
    print(("[LUCK] running %s   %d gradients   %d strokes   %d fps"):format(
        conn and "yes" or "no", #gradients, #strokes, L.ThemeFps))
end

-- --------------------------------------------------------------------
-- The picker
-- --------------------------------------------------------------------
local function buildPicker()
    local gui = themedGui
    if not gui then return end

    local ROWS = math.ceil(#THEMES / 2)
    local LIST_H = 12 + ROWS * 36
    local EDIT_H = 118
    local W, H = 214, 40 + LIST_H + EDIT_H
    local root = Instance.new("Frame")
    root.Name = "LuckThemePicker"
    root.Size = UDim2.new(0, W, 0, H)
    root.Position = UDim2.new(0, 16, 0, 210)
    root.BackgroundColor3 = rgb(8, 17, 11)
    root.BackgroundTransparency = 0.12
    root.BorderSizePixel = 0
    root.Visible = false
    root.Parent = gui
    Instance.new("UICorner", root).CornerRadius = UDim.new(0, 14)

    local edge = Instance.new("UIStroke", root)
    edge.Thickness = 1
    edge.Transparency = 0.5

    -- Registered by hand, because the panel walk already ran and there is no
    -- DescendantAdded hook to catch these.
    strokes[#strokes + 1] = edge
    attach(root)

    local header = Instance.new("TextButton")
    header.Size = UDim2.new(1, 0, 0, 28)
    header.BackgroundTransparency = 1
    header.Text = ""
    header.AutoButtonColor = false
    header.Parent = root

    local title = Instance.new("TextLabel")
    title.Size = UDim2.new(1, -20, 1, 0)
    title.Position = UDim2.new(0, 12, 0, 0)
    title.BackgroundTransparency = 1
    title.Text = "THEME"
    title.TextColor3 = rgb(165, 255, 198)
    title.Font = Enum.Font.GothamBold
    title.TextSize = 11
    title.TextXAlignment = Enum.TextXAlignment.Left
    title.Parent = header

    local nameLabel = Instance.new("TextLabel")
    nameLabel.Size = UDim2.new(1, -20, 0, 12)
    nameLabel.Position = UDim2.new(0, 12, 0, 26)
    nameLabel.BackgroundTransparency = 1
    nameLabel.Text = L.Theme
    nameLabel.TextColor3 = (L.Palette and L.Palette.MUTED) or rgb(108, 148, 120)
    nameLabel.Font = Enum.Font.GothamSemibold
    nameLabel.TextSize = 9
    nameLabel.TextXAlignment = Enum.TextXAlignment.Left
    nameLabel.Parent = root

    -- Body, so minimising is one Visible flip rather than ten. Collapsed, the
    -- panel is just its header -- same behaviour as the script's own panels.
    local body = Instance.new("Frame")
    body.Name = "Body"
    body.Size = UDim2.new(1, 0, 1, -40)
    body.Position = UDim2.new(0, 0, 0, 40)
    body.BackgroundTransparency = 1
    body.Parent = root

    local minBtn = Instance.new("TextButton")
    minBtn.Size = UDim2.new(0, 18, 0, 18)
    minBtn.Position = UDim2.new(1, -46, 0.5, -9)
    minBtn.BackgroundColor3 = (L.Palette and L.Palette.RAISED) or rgb(17, 36, 23)
    minBtn.Text = "-"
    minBtn.TextColor3 = (L.Palette and L.Palette.ACCENT) or rgb(74, 222, 128)
    minBtn.Font = Enum.Font.GothamBold
    minBtn.TextSize = 12
    minBtn.AutoButtonColor = false
    minBtn.BorderSizePixel = 0
    minBtn.Parent = header
    Instance.new("UICorner", minBtn).CornerRadius = UDim.new(0, 6)

    local hideBtn = Instance.new("TextButton")
    hideBtn.Size = UDim2.new(0, 18, 0, 18)
    hideBtn.Position = UDim2.new(1, -24, 0.5, -9)
    hideBtn.BackgroundColor3 = (L.Palette and L.Palette.RAISED) or rgb(17, 36, 23)
    hideBtn.Text = "x"
    hideBtn.TextColor3 = (L.Palette and L.Palette.RED) or rgb(255, 130, 155)
    hideBtn.Font = Enum.Font.GothamBold
    hideBtn.TextSize = 11
    hideBtn.AutoButtonColor = false
    hideBtn.BorderSizePixel = 0
    hideBtn.Parent = header
    Instance.new("UICorner", hideBtn).CornerRadius = UDim.new(0, 6)

    local minimized = false
    local editorOpen = function() return L.Theme == "Custom" end
    local function applyMin()
        minBtn.Text = minimized and "+" or "-"
        body.Visible = not minimized
        nameLabel.Visible = not minimized
        root.Size = minimized and UDim2.new(0, W, 0, 28)
            or UDim2.new(0, W, 0, editorOpen() and H or (40 + LIST_H))
    end
    L.MinimizeThemePanel = function(on)
        if on == nil then on = not minimized end
        minimized = on and true or false
        applyMin()
        pcall(function() writefile(MIN_FILE, minimized and "1" or "0") end)
        return minimized
    end
    minBtn.MouseButton1Click:Connect(function() L.MinimizeThemePanel() end)
    hideBtn.MouseButton1Click:Connect(function()
        if L.ToggleThemePanel then L.ToggleThemePanel(false) end
    end)

    -- Drag. The InputChanged handler is connected only while a drag is in
    -- progress and dropped on release, so this is not a permanent global
    -- callback firing on every mouse move -- the base script went to the
    -- trouble of collapsing six of those into one and this must not add a
    -- seventh.
    --
    -- Wrapped, because the picker is cosmetic: an executor or GUI parent that
    -- does not hand out one of these signals should cost the drag, not the
    -- whole panel.
    pcall(function()
        local startPos, startAt, moveConn
        local function stopDrag()
            if moveConn then
                pcall(function() moveConn:Disconnect() end)
                moveConn = nil
            end
        end
        header.InputBegan:Connect(function(i)
            if i.UserInputType ~= Enum.UserInputType.MouseButton1
                and i.UserInputType ~= Enum.UserInputType.Touch then return end
            startAt, startPos = i.Position, root.Position
            stopDrag()
            moveConn = UIS.InputChanged:Connect(function(m)
                if m.UserInputType ~= Enum.UserInputType.MouseMovement
                    and m.UserInputType ~= Enum.UserInputType.Touch then return end
                local d = m.Position - startAt
                root.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + d.X,
                                          startPos.Y.Scale, startPos.Y.Offset + d.Y)
            end)
            i.Changed:Connect(function()
                if i.UserInputState == Enum.UserInputState.End then stopDrag() end
            end)
        end)
        if header.InputEnded then
            header.InputEnded:Connect(function(i)
                if i.UserInputType == Enum.UserInputType.MouseButton1
                    or i.UserInputType == Enum.UserInputType.Touch then stopDrag() end
            end)
        end
    end)

    local rows = {}
    for i, theme in ipairs(THEMES) do
        local col = (i - 1) % 2
        local row = floor((i - 1) / 2)
        local b = Instance.new("TextButton")
        b.Size = UDim2.new(0, 92, 0, 30)
        b.Position = UDim2.new(0, 12 + col * 98, 0, 6 + row * 36)
        b.BackgroundColor3 = rgb(17, 36, 23)
        b.Text = ""
        b.AutoButtonColor = false
        b.BorderSizePixel = 0
        b.Parent = body
        Instance.new("UICorner", b).CornerRadius = UDim.new(0, 8)

        -- Each swatch wears its own palette so the list reads as colours,
        -- not as ten identical buttons with words on them.
        local sw = Instance.new("Frame")
        sw.Size = UDim2.new(0, 22, 0, 18)
        sw.Position = UDim2.new(0, 6, 0.5, -9)
        sw.BackgroundColor3 = theme.accent
        sw.BorderSizePixel = 0
        sw.Parent = b
        Instance.new("UICorner", sw).CornerRadius = UDim.new(0, 5)

        local sg = Instance.new("UIGradient")
        sg.Rotation = 25
        sg.Parent = sw
        if theme.hue then
            local kps = table.create(8)
            for k = 1, 8 do
                local t = (k - 1) / 7
                kps[k] = ColorSequenceKeypoint.new(t, hsv(t * 0.92, 0.82, 1))
            end
            sg.Color = ColorSequence.new(kps)
        else
            local ramp = rampFor(theme)
            local kps = table.create(#ramp)
            for k, e in ipairs(ramp) do
                kps[k] = ColorSequenceKeypoint.new(e.t, e.v)
            end
            sg.Color = ColorSequence.new(kps)
        end
        swatches[#swatches + 1] = {frame = sw, grad = sg, theme = theme}

        local lbl = Instance.new("TextLabel")
        lbl.Size = UDim2.new(1, -36, 1, 0)
        lbl.Position = UDim2.new(0, 34, 0, 0)
        lbl.BackgroundTransparency = 1
        lbl.Text = theme.name
        lbl.TextColor3 = rgb(228, 246, 233)
        lbl.Font = Enum.Font.GothamBold
        lbl.TextSize = 10
        lbl.TextXAlignment = Enum.TextXAlignment.Left
        lbl.Parent = b

        b.MouseButton1Click:Connect(function() L.SetTheme(theme.name) end)
        rows[i] = {button = b, label = lbl, theme = theme}
    end

    -- ----------------------------------------------------------------
    -- Custom editor
    --
    -- Four slots and three sliders, rather than twelve sliders: pick the slot,
    -- then move R/G/B. The slots run dark to light because that is the order the
    -- ramp flows through, so slot 1 is the shadow and slot 4 the highlight.
    -- ----------------------------------------------------------------
    local editor = Instance.new("Frame")
    editor.Name = "CustomEditor"
    editor.Size = UDim2.new(1, 0, 0, EDIT_H)
    editor.Position = UDim2.new(0, 0, 0, LIST_H)
    editor.BackgroundTransparency = 1
    editor.Visible = false
    editor.Parent = body

    local slotTag = Instance.new("TextLabel")
    slotTag.Size = UDim2.new(1, -24, 0, 11)
    slotTag.Position = UDim2.new(0, 12, 0, 0)
    slotTag.BackgroundTransparency = 1
    slotTag.Text = "SLOT  ·  dark to light"
    slotTag.TextColor3 = (L.Palette and L.Palette.MUTED) or rgb(108, 148, 120)
    slotTag.Font = Enum.Font.GothamSemibold
    slotTag.TextSize = 8
    slotTag.TextXAlignment = Enum.TextXAlignment.Left
    slotTag.Parent = editor

    local activeSlot = 3
    local slotBtns, sliders = {}, {}

    for i = 1, L.CustomSlots do
        local b = Instance.new("TextButton")
        b.Size = UDim2.new(0, 44, 0, 20)
        b.Position = UDim2.new(0, 12 + (i - 1) * 48, 0, 14)
        b.BackgroundColor3 = CUSTOM.colors[i]
        b.Text = ""
        b.AutoButtonColor = false
        b.BorderSizePixel = 0
        b.Parent = editor
        Instance.new("UICorner", b).CornerRadius = UDim.new(0, 6)
        local ring = Instance.new("UIStroke", b)
        ring.Thickness = 2
        ring.Transparency = 1
        b.MouseButton1Click:Connect(function()
            activeSlot = i
            if refreshCustomUI then refreshCustomUI() end
        end)
        slotBtns[i] = {button = b, ring = ring}
    end

    -- One shared InputChanged, connected while a knob is held and dropped on
    -- release. Three permanent mouse-move handlers for three sliders is exactly
    -- what the base script went to the trouble of collapsing.
    local function makeSlider(y, label, tint, channel)
        local lbl = Instance.new("TextLabel")
        lbl.Size = UDim2.new(0, 14, 0, 14)
        lbl.Position = UDim2.new(0, 12, 0, y)
        lbl.BackgroundTransparency = 1
        lbl.Text = label
        lbl.TextColor3 = tint
        lbl.Font = Enum.Font.GothamBold
        lbl.TextSize = 10
        lbl.Parent = editor

        local track = Instance.new("Frame")
        track.Size = UDim2.new(1, -84, 0, 6)
        track.Position = UDim2.new(0, 30, 0, y + 4)
        track.BackgroundColor3 = (L.Palette and L.Palette.RAISED) or rgb(17, 36, 23)
        track.BorderSizePixel = 0
        track.Parent = editor
        Instance.new("UICorner", track).CornerRadius = UDim.new(0, 3)

        local fill = Instance.new("Frame")
        fill.Size = UDim2.new(0, 0, 1, 0)
        fill.BackgroundColor3 = tint
        fill.BorderSizePixel = 0
        fill.Parent = track
        Instance.new("UICorner", fill).CornerRadius = UDim.new(0, 3)

        local val = Instance.new("TextLabel")
        val.Size = UDim2.new(0, 30, 0, 14)
        val.Position = UDim2.new(1, -42, 0, y)
        val.BackgroundTransparency = 1
        val.Text = "0"
        val.TextColor3 = (L.Palette and L.Palette.TEXT) or rgb(228, 246, 233)
        val.Font = Enum.Font.GothamSemibold
        val.TextSize = 9
        val.TextXAlignment = Enum.TextXAlignment.Right
        val.Parent = editor

        -- Taller than the track so it can actually be grabbed.
        local grab = Instance.new("TextButton")
        grab.Size = UDim2.new(1, 0, 0, 18)
        grab.Position = UDim2.new(0, 0, 0, -6)
        grab.BackgroundTransparency = 1
        grab.Text = ""
        grab.AutoButtonColor = false
        grab.Parent = track

        local function fromX(x)
            local origin = track.AbsolutePosition.X
            local width = track.AbsoluteSize.X
            if width <= 0 then return 0 end
            return math.clamp((x - origin) / width, 0, 1)
        end
        local function push(alpha)
            local r, g, b = L.GetCustomColor(activeSlot)
            if not r then return end
            local v = floor(alpha * 255 + 0.5)
            if channel == "R" then r = v elseif channel == "G" then g = v else b = v end
            L.SetCustomColor(activeSlot, r, g, b)
        end

        pcall(function()
            local moveConn
            local function release()
                if moveConn then
                    pcall(function() moveConn:Disconnect() end)
                    moveConn = nil
                end
            end
            grab.InputBegan:Connect(function(i)
                if i.UserInputType ~= Enum.UserInputType.MouseButton1
                    and i.UserInputType ~= Enum.UserInputType.Touch then return end
                push(fromX(i.Position.X))
                release()
                moveConn = UIS.InputChanged:Connect(function(m)
                    if m.UserInputType ~= Enum.UserInputType.MouseMovement
                        and m.UserInputType ~= Enum.UserInputType.Touch then return end
                    push(fromX(m.Position.X))
                end)
                i.Changed:Connect(function()
                    if i.UserInputState == Enum.UserInputState.End then release() end
                end)
            end)
            if grab.InputEnded then
                grab.InputEnded:Connect(function(i)
                    if i.UserInputType == Enum.UserInputType.MouseButton1
                        or i.UserInputType == Enum.UserInputType.Touch then release() end
                end)
            end
        end)

        sliders[channel] = {fill = fill, value = val}
    end

    makeSlider(42, "R", rgb(255, 110, 120), "R")
    makeSlider(62, "G", rgb(120, 235, 140), "G")
    makeSlider(82, "B", rgb(120, 175, 255), "B")

    local randBtn = Instance.new("TextButton")
    randBtn.Size = UDim2.new(1, -24, 0, 20)
    randBtn.Position = UDim2.new(0, 12, 0, 100)
    randBtn.BackgroundColor3 = (L.Palette and L.Palette.RAISED) or rgb(17, 36, 23)
    randBtn.Text = "RANDOM"
    randBtn.TextColor3 = (L.Palette and L.Palette.ACCENT) or rgb(74, 222, 128)
    randBtn.Font = Enum.Font.GothamBold
    randBtn.TextSize = 10
    randBtn.AutoButtonColor = false
    randBtn.BorderSizePixel = 0
    randBtn.Parent = editor
    Instance.new("UICorner", randBtn).CornerRadius = UDim.new(0, 6)
    randBtn.MouseButton1Click:Connect(function() L.RandomCustom() end)

    refreshCustomUI = function()
        for i, sb in ipairs(slotBtns) do
            sb.button.BackgroundColor3 = CUSTOM.colors[i]
            sb.ring.Transparency = (i == activeSlot) and 0.1 or 1
            sb.ring.Color = (L.Palette and L.Palette.HIGH) or rgb(165, 255, 198)
        end
        local r, g, b = L.GetCustomColor(activeSlot)
        if not r then return end
        local vals = {R = r, G = g, B = b}
        for ch, sl in pairs(sliders) do
            sl.fill.Size = UDim2.new(vals[ch] / 255, 0, 1, 0)
            sl.value.Text = tostring(vals[ch])
        end
    end

    repaintPicker = function()
        nameLabel.Text = L.Theme
        for _, r in ipairs(rows) do
            local on = r.theme.name == L.Theme
            r.button.BackgroundColor3 = on and rgb(31, 60, 41) or rgb(17, 36, 23)
            r.label.TextColor3 = on and r.theme.accent or rgb(160, 190, 170)
        end
        -- The editor is only in the way when a fixed palette is picked.
        editor.Visible = (L.Theme == "Custom")
        root.Size = minimized and UDim2.new(0, W, 0, 28)
            or UDim2.new(0, W, 0, editor.Visible and H or (40 + LIST_H))
        refreshCustomUI()
    end
    repaintPicker()

    -- restore whatever it was left as
    local savedMin = false
    pcall(function()
        if type(isfile) == "function" and not isfile(MIN_FILE) then return end
        savedMin = readfile(MIN_FILE) == "1"
    end)
    minimized = savedMin
    applyMin()

    L.ThemePanel = root
    L.ToggleThemePanel = function(on)
        if on == nil then on = not root.Visible end
        root.Visible = on and true or false
        return root.Visible
    end
end

-- --------------------------------------------------------------------
-- Boot
--
-- Registered on the readiness gate after the UI's own build, so the panels
-- exist by the time this runs. Nothing here polls for them.
-- --------------------------------------------------------------------
local function boot()
    if not attachAll() then return end
    buildPicker()
    if L.ToggleThemePanel then L.ToggleThemePanel(true) end

    -- Cycle key. Defaults to RightBracket; LUCK.ThemeKey = Enum.KeyCode.X
    -- to move it, or nil to turn it off.
    L.ThemeKey = Enum.KeyCode.RightBracket
    UIS.InputBegan:Connect(function(input, typing)
        if typing or not L.ThemeKey then return end
        if input.KeyCode == L.ThemeKey then L.NextTheme() end
    end)

    print("[LUCK] PRIVATE  ·  " .. #THEMES .. " themes  ·  " .. tostring(L.Theme))
    print("[LUCK] LUCK.SetTheme(\"Clover\")  ·  LUCK.NextTheme()  ·  ] to cycle")
end

-- Errors are reported, not swallowed. A theme engine that half-builds and says
-- nothing is worse than one that does not build at all.
local function safeBoot()
    local ok, err = pcall(boot)
    if not ok then
        L.ThemeError = tostring(err)
        warn("[LUCK] theme engine failed: " .. tostring(err))
    end
end

if L.WhenReady then
    L.WhenReady(safeBoot)
else
    task.defer(safeBoot)
end

end

--[[ ====================================================================
     LUCK PRIVATE  ·  win sound

     Plays when a redeem comes back a win. Cycle the picker to hear each
     one, TEST to replay the current one, and the name is on screen so
     there is something to point at.

     rbxasset:// ids are files inside the Roblox client -- no lookup, no
     moderation, they cannot 404. Anything uploaded can, so the picker
     marks a sound that never loads instead of just going quiet.
     ==================================================================== }]]

do

local L = (getgenv and getgenv().LUCK) or LUCK
if not L then return end

local UIS = game:GetService("UserInputService")
local rgb = Color3.fromRGB
local floor = math.floor

L.WinSounds = {
    {name = "Ping",       id = "rbxasset://sounds/electronicpingshort.wav"},
    {name = "Snap",       id = "rbxasset://sounds/snap.wav"},
    {name = "Pop",        id = "rbxasset://sounds/pop_mid_up.wav"},
    {name = "Button",     id = "rbxasset://sounds/button.wav"},
    {name = "Switch",     id = "rbxasset://sounds/switch.wav"},
    {name = "Click",      id = "rbxasset://sounds/clickfast.wav"},
    {name = "Bass",       id = "rbxasset://sounds/bass.wav"},
    {name = "Swoosh",     id = "rbxasset://sounds/swoosh.wav"},
    {name = "Water",      id = "rbxasset://sounds/impact_water.mp3"},
    {name = "Blop",       id = "rbxassetid://138213892284919"},
}

L.WinSoundOn     = true
L.WinSoundVolume = 0.55
L.WinSoundIndex  = 1
L.WinSoundDead   = {}      -- names that never loaded

local SOUND_FILE = "LUCK/private_sound.txt"
local VOL_FILE   = "LUCK/private_sound_vol.txt"

local function save()
    pcall(function()
        if type(makefolder) == "function"
            and (type(isfolder) ~= "function" or not isfolder("LUCK")) then
            makefolder("LUCK")
        end
        local cur = L.WinSounds[L.WinSoundIndex]
        writefile(SOUND_FILE, (L.WinSoundOn and "" or "off:")
            .. (cur and cur.name or "Ping"))
        writefile(VOL_FILE, tostring(L.WinSoundVolume))
    end)
end

local function load()
    pcall(function()
        if type(isfile) == "function" and not isfile(SOUND_FILE) then return end
        local raw = readfile(SOUND_FILE)
        if type(raw) ~= "string" then return end
        if raw:sub(1, 4) == "off:" then
            L.WinSoundOn, raw = false, raw:sub(5)
        end
        for i, e in ipairs(L.WinSounds) do
            if e.name == raw then L.WinSoundIndex = i break end
        end
    end)
    pcall(function()
        if type(isfile) == "function" and not isfile(VOL_FILE) then return end
        local v = tonumber(readfile(VOL_FILE))
        if v then L.WinSoundVolume = math.clamp(v, 0, 1) end
    end)
end
load()

-- One Sound instance, reused. A fresh one per win is an Instance allocation on
-- the result path for something that only ever plays one clip at a time.
local player
local function ensure()
    if player and player.Parent then return player end
    local ok = pcall(function()
        local s = Instance.new("Sound")
        s.Name = "LuckWinSound"
        s.Volume = L.WinSoundVolume
        local parent
        pcall(function() parent = game:GetService("SoundService") end)
        s.Parent = parent or L.GuiParent
        player = s
    end)
    return ok and player or nil
end

local refreshSoundUI

L.CurrentWinSound = function()
    return L.WinSounds[L.WinSoundIndex] or L.WinSounds[1]
end

L.PlayWinSound = function()
    if not L.WinSoundOn then return false end
    local s = ensure()
    local entry = L.CurrentWinSound()
    if not s or not entry then return false end
    pcall(function()
        s.SoundId = entry.id
        s.Volume = L.WinSoundVolume
        s:Play()
    end)
    return true
end

-- TEST ignores the on/off switch: you press it to hear the sound, not to find
-- out whether the switch is on.
L.TestWinSound = function()
    local s = ensure()
    local entry = L.CurrentWinSound()
    if not s or not entry then return false end
    pcall(function()
        s.SoundId = entry.id
        s.Volume = L.WinSoundVolume
        s:Play()
    end)
    print(("[LUCK] sound  %s  ->  %s"):format(entry.name, entry.id))

    -- A dead id plays nothing and says nothing, which is indistinguishable from
    -- a quiet one. Give it a moment and mark it if it never loads.
    task.spawn(function()
        local name = entry.name
        for _ = 1, 20 do
            local okLoaded, loaded = pcall(function()
                return s.IsLoaded or (s.TimeLength or 0) > 0
            end)
            if okLoaded and loaded then
                if L.WinSoundDead[name] then
                    L.WinSoundDead[name] = nil
                    if refreshSoundUI then refreshSoundUI() end
                end
                return
            end
            task.wait(0.15)
        end
        L.WinSoundDead[name] = true
        if refreshSoundUI then refreshSoundUI() end
        warn(("[LUCK] sound '%s' did not load: %s"):format(name, entry.id))
    end)
    return true
end

L.NextWinSound = function(step)
    local n = #L.WinSounds
    L.WinSoundIndex = ((L.WinSoundIndex - 1 + (step or 1)) % n) + 1
    save()
    if refreshSoundUI then refreshSoundUI() end
    L.TestWinSound()
    return L.CurrentWinSound().name
end

L.SetWinSound = function(name)
    for i, e in ipairs(L.WinSounds) do
        if e.name:lower() == tostring(name):lower() then
            L.WinSoundIndex = i
            save()
            if refreshSoundUI then refreshSoundUI() end
            return true
        end
    end
    -- Anything that is not one of the names is treated as an id to add.
    local id = tostring(name)
    if id:match("^rbxasset") then
        L.WinSounds[#L.WinSounds + 1] = {name = "Custom", id = id}
        L.WinSoundIndex = #L.WinSounds
        save()
        if refreshSoundUI then refreshSoundUI() end
        return true
    end
    print("[LUCK] sounds: " .. (function()
        local out = {}
        for _, e in ipairs(L.WinSounds) do out[#out + 1] = e.name end
        return table.concat(out, ", ")
    end)())
    return false
end

L.SetWinSoundOn = function(on)
    if on == nil then on = not L.WinSoundOn end
    L.WinSoundOn = on and true or false
    save()
    if refreshSoundUI then refreshSoundUI() end
    return L.WinSoundOn
end

-- The hook the base fires once a redeem has been answered.
do
    local prev = L.OnResult
    L.OnResult = function(code, ok, reply, timing)
        if prev then pcall(prev, code, ok, reply, timing) end
        if ok == true then L.PlayWinSound() end
    end
end

-- --------------------------------------------------------------------
-- Panel
-- --------------------------------------------------------------------
local function findGui()
    local parent = L.GuiParent
    if not parent then return nil end
    for _, d in ipairs(parent:GetChildren()) do
        if d:IsA("ScreenGui") and tostring(d.Name):match("^LUCK_%d+$") then
            return d
        end
    end
    return nil
end

local function buildPanel()
    local gui = findGui()
    if not gui then return end
    local P = L.Palette or {}
    local W, H = 214, 116

    local root = Instance.new("Frame")
    root.Name = "LuckSoundPanel"
    root.Size = UDim2.new(0, W, 0, H)
    root.Position = UDim2.new(0, 240, 0, 210)
    root.BackgroundColor3 = P.BG or rgb(8, 17, 11)
    root.BackgroundTransparency = 0.12
    root.BorderSizePixel = 0
    root.Parent = gui
    Instance.new("UICorner", root).CornerRadius = UDim.new(0, 14)
    local edge = Instance.new("UIStroke", root)
    edge.Thickness = 1
    edge.Transparency = 0.5
    edge.Color = P.LINE or rgb(31, 60, 41)

    local header = Instance.new("TextButton")
    header.Size = UDim2.new(1, 0, 0, 28)
    header.BackgroundTransparency = 1
    header.Text = ""
    header.AutoButtonColor = false
    header.Parent = root

    local title = Instance.new("TextLabel")
    title.Size = UDim2.new(1, -70, 1, 0)
    title.Position = UDim2.new(0, 12, 0, 0)
    title.BackgroundTransparency = 1
    title.Text = "WIN SOUND"
    title.TextColor3 = P.HIGH or rgb(165, 255, 198)
    title.Font = Enum.Font.GothamBold
    title.TextSize = 11
    title.TextXAlignment = Enum.TextXAlignment.Left
    title.Parent = header

    local body = Instance.new("Frame")
    body.Name = "Body"
    body.Size = UDim2.new(1, 0, 1, -28)
    body.Position = UDim2.new(0, 0, 0, 28)
    body.BackgroundTransparency = 1
    body.Parent = root

    local minimized = false
    local minBtn = Instance.new("TextButton")
    minBtn.Size = UDim2.new(0, 18, 0, 18)
    minBtn.Position = UDim2.new(1, -46, 0.5, -9)
    minBtn.BackgroundColor3 = P.RAISED or rgb(17, 36, 23)
    minBtn.Text = "-"
    minBtn.TextColor3 = P.ACCENT or rgb(74, 222, 128)
    minBtn.Font = Enum.Font.GothamBold
    minBtn.TextSize = 12
    minBtn.AutoButtonColor = false
    minBtn.BorderSizePixel = 0
    minBtn.Parent = header
    Instance.new("UICorner", minBtn).CornerRadius = UDim.new(0, 6)

    local hideBtn = Instance.new("TextButton")
    hideBtn.Size = UDim2.new(0, 18, 0, 18)
    hideBtn.Position = UDim2.new(1, -24, 0.5, -9)
    hideBtn.BackgroundColor3 = P.RAISED or rgb(17, 36, 23)
    hideBtn.Text = "x"
    hideBtn.TextColor3 = P.RED or rgb(255, 130, 155)
    hideBtn.Font = Enum.Font.GothamBold
    hideBtn.TextSize = 11
    hideBtn.AutoButtonColor = false
    hideBtn.BorderSizePixel = 0
    hideBtn.Parent = header
    Instance.new("UICorner", hideBtn).CornerRadius = UDim.new(0, 6)

    local function applyMin()
        minBtn.Text = minimized and "+" or "-"
        body.Visible = not minimized
        root.Size = minimized and UDim2.new(0, W, 0, 28) or UDim2.new(0, W, 0, H)
    end
    L.MinimizeSoundPanel = function(on)
        if on == nil then on = not minimized end
        minimized = on and true or false
        applyMin()
        return minimized
    end
    minBtn.MouseButton1Click:Connect(function() L.MinimizeSoundPanel() end)
    hideBtn.MouseButton1Click:Connect(function() root.Visible = false end)
    L.ToggleSoundPanel = function(on)
        if on == nil then on = not root.Visible end
        root.Visible = on and true or false
        return root.Visible
    end

    -- drag, connected only while held
    pcall(function()
        local startAt, startPos, moveConn
        local function release()
            if moveConn then
                pcall(function() moveConn:Disconnect() end)
                moveConn = nil
            end
        end
        header.InputBegan:Connect(function(i)
            if i.UserInputType ~= Enum.UserInputType.MouseButton1
                and i.UserInputType ~= Enum.UserInputType.Touch then return end
            startAt, startPos = i.Position, root.Position
            release()
            moveConn = UIS.InputChanged:Connect(function(m)
                if m.UserInputType ~= Enum.UserInputType.MouseMovement
                    and m.UserInputType ~= Enum.UserInputType.Touch then return end
                local d = m.Position - startAt
                root.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + d.X,
                                          startPos.Y.Scale, startPos.Y.Offset + d.Y)
            end)
            i.Changed:Connect(function()
                if i.UserInputState == Enum.UserInputState.End then release() end
            end)
        end)
    end)

    -- The name, big enough to read across the room, because the whole point is
    -- being able to say which one you want.
    local nameLabel = Instance.new("TextLabel")
    nameLabel.Size = UDim2.new(1, -84, 0, 26)
    nameLabel.Position = UDim2.new(0, 42, 0, 4)
    nameLabel.BackgroundTransparency = 1
    nameLabel.Text = "Ping"
    nameLabel.TextColor3 = P.TEXT or rgb(228, 246, 233)
    nameLabel.Font = Enum.Font.GothamBold
    nameLabel.TextSize = 15
    nameLabel.Parent = body

    local idLabel = Instance.new("TextLabel")
    idLabel.Size = UDim2.new(1, -24, 0, 10)
    idLabel.Position = UDim2.new(0, 12, 0, 30)
    idLabel.BackgroundTransparency = 1
    idLabel.Text = ""
    idLabel.TextColor3 = P.MUTED or rgb(108, 148, 120)
    idLabel.Font = Enum.Font.GothamSemibold
    idLabel.TextSize = 8
    idLabel.TextTruncate = Enum.TextTruncate.AtEnd
    idLabel.Parent = body

    local function arrow(x, txt, step)
        local b = Instance.new("TextButton")
        b.Size = UDim2.new(0, 26, 0, 26)
        b.Position = UDim2.new(x, x == 0 and 12 or -38, 0, 4)
        b.BackgroundColor3 = P.RAISED or rgb(17, 36, 23)
        b.Text = txt
        b.TextColor3 = P.ACCENT or rgb(74, 222, 128)
        b.Font = Enum.Font.GothamBold
        b.TextSize = 13
        b.AutoButtonColor = false
        b.BorderSizePixel = 0
        b.Parent = body
        Instance.new("UICorner", b).CornerRadius = UDim.new(0, 7)
        -- Cycling plays what it lands on, so one button is both "next" and
        -- "let me hear it".
        b.MouseButton1Click:Connect(function() L.NextWinSound(step) end)
        return b
    end
    arrow(0, "<", -1)
    arrow(1, ">", 1)

    local testBtn = Instance.new("TextButton")
    testBtn.Size = UDim2.new(0, 118, 0, 24)
    testBtn.Position = UDim2.new(0, 12, 0, 46)
    testBtn.BackgroundColor3 = P.RAISED or rgb(17, 36, 23)
    testBtn.Text = "TEST"
    testBtn.TextColor3 = P.HIGH or rgb(165, 255, 198)
    testBtn.Font = Enum.Font.GothamBold
    testBtn.TextSize = 11
    testBtn.AutoButtonColor = false
    testBtn.BorderSizePixel = 0
    testBtn.Parent = body
    Instance.new("UICorner", testBtn).CornerRadius = UDim.new(0, 7)
    testBtn.MouseButton1Click:Connect(function() L.TestWinSound() end)

    local onBtn = Instance.new("TextButton")
    onBtn.Size = UDim2.new(0, 60, 0, 24)
    onBtn.Position = UDim2.new(1, -72, 0, 46)
    onBtn.BackgroundColor3 = P.RAISED or rgb(17, 36, 23)
    onBtn.Text = "ON"
    onBtn.TextColor3 = P.ACCENT or rgb(74, 222, 128)
    onBtn.Font = Enum.Font.GothamBold
    onBtn.TextSize = 11
    onBtn.AutoButtonColor = false
    onBtn.BorderSizePixel = 0
    onBtn.Parent = body
    Instance.new("UICorner", onBtn).CornerRadius = UDim.new(0, 7)
    onBtn.MouseButton1Click:Connect(function() L.SetWinSoundOn() end)

    local volTrack = Instance.new("Frame")
    volTrack.Size = UDim2.new(1, -60, 0, 6)
    volTrack.Position = UDim2.new(0, 40, 0, 78)
    volTrack.BackgroundColor3 = P.RAISED or rgb(17, 36, 23)
    volTrack.BorderSizePixel = 0
    volTrack.Parent = body
    Instance.new("UICorner", volTrack).CornerRadius = UDim.new(0, 3)

    local volFill = Instance.new("Frame")
    volFill.Size = UDim2.new(L.WinSoundVolume, 0, 1, 0)
    volFill.BackgroundColor3 = P.ACCENT or rgb(74, 222, 128)
    volFill.BorderSizePixel = 0
    volFill.Parent = volTrack
    Instance.new("UICorner", volFill).CornerRadius = UDim.new(0, 3)

    local volTag = Instance.new("TextLabel")
    volTag.Size = UDim2.new(0, 26, 0, 12)
    volTag.Position = UDim2.new(0, 12, 0, 75)
    volTag.BackgroundTransparency = 1
    volTag.Text = "VOL"
    volTag.TextColor3 = P.MUTED or rgb(108, 148, 120)
    volTag.Font = Enum.Font.GothamBold
    volTag.TextSize = 8
    volTag.Parent = body

    local volGrab = Instance.new("TextButton")
    volGrab.Size = UDim2.new(1, 0, 0, 18)
    volGrab.Position = UDim2.new(0, 0, 0, -6)
    volGrab.BackgroundTransparency = 1
    volGrab.Text = ""
    volGrab.AutoButtonColor = false
    volGrab.Parent = volTrack

    pcall(function()
        local moveConn
        local function release()
            if moveConn then
                pcall(function() moveConn:Disconnect() end)
                moveConn = nil
            end
        end
        local function set(x)
            local origin, width = volTrack.AbsolutePosition.X, volTrack.AbsoluteSize.X
            if width <= 0 then return end
            L.WinSoundVolume = math.clamp((x - origin) / width, 0, 1)
            volFill.Size = UDim2.new(L.WinSoundVolume, 0, 1, 0)
            save()
        end
        volGrab.InputBegan:Connect(function(i)
            if i.UserInputType ~= Enum.UserInputType.MouseButton1
                and i.UserInputType ~= Enum.UserInputType.Touch then return end
            set(i.Position.X)
            release()
            moveConn = UIS.InputChanged:Connect(function(m)
                if m.UserInputType ~= Enum.UserInputType.MouseMovement
                    and m.UserInputType ~= Enum.UserInputType.Touch then return end
                set(m.Position.X)
            end)
            i.Changed:Connect(function()
                if i.UserInputState == Enum.UserInputState.End then release() end
            end)
        end)
    end)

    refreshSoundUI = function()
        local e = L.CurrentWinSound()
        if not e then return end
        local dead = L.WinSoundDead[e.name]
        nameLabel.Text = ("%d/%d  %s"):format(L.WinSoundIndex, #L.WinSounds, e.name)
        nameLabel.TextColor3 = dead and (P.RED or rgb(255, 130, 155))
            or (P.TEXT or rgb(228, 246, 233))
        idLabel.Text = dead and ("did not load  ·  " .. e.id) or e.id
        onBtn.Text = L.WinSoundOn and "ON" or "OFF"
        onBtn.TextColor3 = L.WinSoundOn and (P.ACCENT or rgb(74, 222, 128))
            or (P.MUTED or rgb(108, 148, 120))
        volFill.Size = UDim2.new(L.WinSoundVolume, 0, 1, 0)
    end
    refreshSoundUI()
    applyMin()

    L.SoundPanel = root
end

local function boot()
    buildPanel()
    print(("[LUCK] win sound  ·  %s  ·  %d to choose from")
        :format(L.CurrentWinSound().name, #L.WinSounds))
    print("[LUCK] LUCK.NextWinSound()  ·  LUCK.TestWinSound()  ·  LUCK.SetWinSound(\"Snap\")")
end

if L.WhenReady then
    L.WhenReady(function()
        local ok, err = pcall(boot)
        if not ok then
            L.SoundError = tostring(err)
            warn("[LUCK] win sound panel failed: " .. tostring(err))
        end
    end)
else
    task.defer(function() pcall(boot) end)
end

end
